"""LZNT1 test vectors made by Windows' own compressor, for the NTFS driver's decompressor (kernel/fs/ntfs_lznt1.c) and for the generator's compressor.

Each vector is (name, recipe, length, crc32, hex) where `recipe` rebuilds the uncompressed bytes (make()), `length` and `crc32` say what they must be (so that a change
in the recipe code is noticed instead of silently testing something else) and `hex` is what ntdll!RtlCompressBuffer produced for them with 4096-byte chunks, the
"standard" engine unless the name ends in -max (COMPRESSION_ENGINE_MAXIMUM). MS-XCA section 2.5 says what the format is; the first vector is its worked example.

On Windows `python tests/host/ntfs_lznt1_vectors.py --regenerate` prints a fresh VECTORS list (it calls RtlCompressBuffer through ctypes; nothing else is needed). On any
system `python tests/host/ntfs_lznt1_vectors.py` checks that the recipes still produce the recorded lengths and checksums.
"""
import struct
import sys
import zlib


def _prng(seed):
    """xorshift64*: the same numbers in every Python version."""
    x = (seed * 0x9E3779B97F4A7C15 + 1) & 0xFFFFFFFFFFFFFFFF
    while True:
        x ^= x >> 12
        x ^= (x << 25) & 0xFFFFFFFFFFFFFFFF
        x ^= x >> 27
        yield (x * 0x2545F4914F6CDD1D) & 0xFFFFFFFFFFFFFFFF


def make(recipe):
    kind, n, seed = recipe
    g = _prng(seed)
    out = bytearray()
    if kind == "xca":                                  # the worked example of MS-XCA 2.5
        return (b"F# F# G A A G F# E D D E F# F# E E F# F# G A A G F# E D D E F# E D D E E F# D E F# G F# D E F# G F# E D E A F# F# G A A G F# E D D E F# E D D\0")
    if kind == "zeros":
        return bytes(n)
    if kind == "text":
        words = [b"gensokyo", b"reimu", b"marisa", b"touhou", b"kappa", b"fairy", b"shrine", b"\n", b" ", b"sakuya", b"patchouli", b"the", b"of"]
        while len(out) < n:
            out += words[next(g) % len(words)]
        return bytes(out[:n])
    if kind == "random":
        while len(out) < n:
            out += struct.pack("<Q", next(g))
        return bytes(out[:n])
    if kind == "rle":                                  # runs of one byte
        while len(out) < n:
            out += bytes([next(g) & 255]) * (1 + next(g) % 300)
        return bytes(out[:n])
    if kind == "cycle":                                # a short period repeated: overlapping copies
        period = bytes(next(g) & 255 for _ in range(seed % 13 + 1))
        return (period * (n // len(period) + 1))[:n]
    if kind == "records":                              # structured binary: counters and small fields
        i = 0
        while len(out) < n:
            out += struct.pack("<IHHQ", i, i & 0xFF, 0x1234, i * 4096)
            i += 1
        return bytes(out[:n])
    if kind == "ramp":
        return bytes(i & 255 for i in range(n))
    if kind == "mixed":                                # text, then noise, then zeros, then text again
        part = n // 4
        return make(("text", part, seed)) + make(("random", part, seed + 1)) + bytes(part) + make(("text", n - 3 * part, seed + 2))
    raise ValueError(kind)


# (name, recipe, length, crc32, compressed hex) - filled in by --regenerate
VECTORS = [
    ('xca-example', ('xca', 0, 0), 142, 0xef04ea39, "38b08846232000204720410010a24701a045204400084501507900c045200524138805b4024a44ef0358028c091601484500be009e000401189000"),
    ('text-1k', ('text', 1000, 1), 1000, 0x3bce1a8a, ""),
    ('text-4096', ('text', 4096, 2), 4096, 0x4551fff0, ""),
    ('text-4097', ('text', 4097, 3), 4097, 0x1408056b, ""),
    ('text-9k', ('text', 9000, 4), 9000, 0x2babec31, ""),
    ('text-9k-max', ('text', 9000, 4), 9000, 0x2babec31, ""),
    ('random-4200', ('random', 4200, 6), 4200, 0x6089b314, ""),
    ('rle-9000', ('rle', 9000, 7), 9000, 0xb3732d25, ""),
    ('cycle-3', ('cycle', 9000, 3), 9000, 0x19ba6d99, "06b01033585cf9f93f06b01033585cf9f93f06b01033585cf92133"),
    ('cycle-1', ('cycle', 9000, 1), 9000, 0x0b6f4af8, "04b0045d10fb1f04b0045d10fb1f04b0045d102313"),
    ('cycle-12-max', ('cycle', 9000, 12), 9000, 0x2cebfa31, "10b000a30cfb16df324524200327e38dbaf0cf10b0000cfb16df324524032027e38dbaa3f0cf10b000fb16df324524032720e38dbaa30c18c3"),
    ('records-6k', ('records', 6000, 8), 6000, 0x32be4c31, ""),
    ('ramp-5000', ('ramp', 5000, 0), 5000, 0xd23996e1, ""),
    ('mixed-12k', ('mixed', 12000, 9), 12000, 0xc0e7d2e0, ""),
    ('mixed-12k-max', ('mixed', 12000, 9), 12000, 0xc0e7d2e0, ""),
    ('one-byte', ('text', 1, 10), 1, 0x856a5aa8, "01b00074"),
    ('three-bytes', ('text', 3, 11), 3, 0x0f70ed2d, "03b00073616b"),
    # zeros-4096: Windows says the buffer is all zeros (nothing to store)
]


def _regenerate():
    import ctypes
    ntdll = ctypes.WinDLL("ntdll")
    ntdll.RtlCompressBuffer.argtypes = [ctypes.c_ushort, ctypes.c_char_p, ctypes.c_ulong, ctypes.c_char_p, ctypes.c_ulong, ctypes.c_ulong,
                                        ctypes.POINTER(ctypes.c_ulong), ctypes.c_void_p]
    specs = [("xca-example", ("xca", 0, 0), 0), ("text-1k", ("text", 1000, 1), 0), ("text-4096", ("text", 4096, 2), 0), ("text-4097", ("text", 4097, 3), 0),
             ("text-9k", ("text", 9000, 4), 0), ("text-9k-max", ("text", 9000, 4), 0x100), ("random-4200", ("random", 4200, 6), 0),
             ("rle-9000", ("rle", 9000, 7), 0), ("cycle-3", ("cycle", 9000, 3), 0), ("cycle-1", ("cycle", 9000, 1), 0), ("cycle-12-max", ("cycle", 9000, 12), 0x100),
             ("records-6k", ("records", 6000, 8), 0), ("ramp-5000", ("ramp", 5000, 0), 0), ("mixed-12k", ("mixed", 12000, 9), 0), ("mixed-12k-max", ("mixed", 12000, 9), 0x100),
             ("one-byte", ("text", 1, 10), 0), ("three-bytes", ("text", 3, 11), 0), ("zeros-4096", ("zeros", 4096, 0), 0)]
    print("VECTORS = [")
    for name, recipe, engine in specs:
        data = make(recipe)
        ws, cws = ctypes.c_ulong(), ctypes.c_ulong()
        st = ntdll.RtlGetCompressionWorkSpaceSize(2 | engine, ctypes.byref(ws), ctypes.byref(cws))
        assert st == 0
        work = ctypes.create_string_buffer(ws.value)
        out = ctypes.create_string_buffer(len(data) + len(data) // 8 + 4096)
        final = ctypes.c_ulong()
        st = ntdll.RtlCompressBuffer(2 | engine, data, len(data), out, len(out), 4096, ctypes.byref(final), work)
        if st & 0xFFFFFFFF == 0x117:                    # STATUS_BUFFER_ALL_ZEROS: Windows reports that an all-zero buffer need not be stored at all
            print(f"    # {name}: Windows says the buffer is all zeros (nothing to store)")
            continue
        assert st == 0, hex(st & 0xFFFFFFFF)
        print(f'    ({name!r}, {recipe!r}, {len(data)}, {zlib.crc32(data) & 0xFFFFFFFF:#010x}, "{out.raw[:final.value].hex()}"),')
    print("]")


if __name__ == "__main__":
    if "--regenerate" in sys.argv:
        _regenerate()
    else:
        bad = 0
        for name, recipe, length, crc, _ in VECTORS:
            data = make(recipe)
            if len(data) != length or zlib.crc32(data) & 0xFFFFFFFF != crc:
                print("recipe changed:", name)
                bad += 1
        print(f"{len(VECTORS)} vectors, {bad} recipes changed")
        sys.exit(1 if bad else 0)
